def generate():
    frozen = json.loads(RESERVED_IDENTITIES.read_text())
    reserved_ids = set(frozen['identities'])
    reserved_domains = set(frozen['domains'])
    rows = []
    for kind, table in (('shared', SHARED), ('go', GO)):
        for family, (identity, domain) in table.items():
            rows.append({'family': family, 'scope': kind, 'identity': identity, 'domain': domain, 'shape_status': 'full root/nested/union freeze remains required'})
    for family, (identity, domain, fields) in IDENTITY_SHAPES.items():
        rows.append({'family': family, 'scope': 'go_source_identity', 'identity': identity, 'domain': domain, 'ordered_fields': ['schema', *fields, 'id'], 'field_types': fields, 'hash_preimage_fields': ['schema', *fields], 'shape_status': 'closed identity-record draft; not source/typing correctness'})
        if family == 'source_type':
            rows[-1]['ordered_fields'] = None
            rows[-1]['hash_preimage_fields'] = None
            rows[-1]['arms'] = {kind: {'ordered_fields': ['schema', 'kind', *arm, 'id'], 'hash_preimage_fields': ['schema', 'kind', *arm], 'field_types': arm} for kind, arm in TYPE_ARMS.items()}
    for profile in ('go_fixed', 'rust_checked', 'go_practical'):
        for kind in ('ai', 'evidence', 'frontend', 'manifest', 'policy', 'release', 'source_map', 'vc', 'vir'):
            rows.append({'family': 'compiled_profile_contract', 'scope': 'shared', 'identity': f'mpk.profile.{kind}.{profile}.v2', 'domain': None, 'shape_status': 'compiled contract/source behavior equivalence freeze remains required'})
    ids = [r['identity'] for r in rows]
    domains = [r['domain'] for r in rows if r['domain']]
    if len(ids) != len(set(ids)) or len(domains) != len(set(domains)) or set(ids) & reserved_ids or set(domains) & reserved_domains:
        raise ValueError('globally unique unreserved candidate identities/domains')
    rows.append({'family': 'compiled_profile_contract_hash', 'scope': 'shared', 'identity': None, 'domain': 'MPK-COMPILED-PROFILE-CONTRACT-2.0', 'shape_status': 'full compiled preimage freeze remains required'})
    return {'schema': 'mpk.go_practical.identity_family_draft.v0', 'status': 'private candidate identities/identity DAG; not normative publication, dispatch or complete artifact freeze', 'profiles_at_v1_activation': list(PROFILES), 'identities': rows, 'type_identity_union': TYPE_ARMS, 'reserved_retired': {'path': RESERVED_IDENTITIES.relative_to(ROOT).as_posix(), 'sha256': sha(RESERVED_IDENTITIES.read_bytes()), 'identities': sorted(reserved_ids), 'domains': sorted(reserved_domains)}, 'retained_generic_identities': ['mpk.release.bundle_inventory.v1'], 'retained_generic_domains': ['MPK-INPUT-SET-0.1', 'MPK-BUNDLE-CONTENT-1.0'], 'retention_condition': 'only exactly unchanged generic fields/preimages/meaning; no retired profile dispatch or widening; full migration review remains due', 'hash_rule': 'SHA256(ASCII(domain) || 0x00 || narrowed RFC8785 JSON of all exact preimage fields); no LF; lowercase hex', 'pending': ['complete all shared/Go root/nested/tagged-union and operation/expression schemas and cross-artifact predicates', 'full reviewed producer/consumer migration and complete profile preservation/activation/rollback protocol', 'independent production source/typed import, hash/identifier/root closure proofs, W05/T01 gate and T02–T11 implementation/releases']}
